/* yakov.LLM search engine for the browser: the same tokenizer and BM25 as
 * yakovllm/tokenizer.py and yakovllm/search.py, line for line, so the static
 * demo returns exactly the results the Python server returns.
 * tests/test_parity.py runs both on the evaluation questions and compares. */
(function (root) {
  'use strict';

  const K1 = 1.2, B = 0.75, META_WEIGHT = 3, REPO_BOOST = 1.6, README_BOOST = 1.15;
  const TEST_PENALTY = 0.8, MAX_PER_FILE = 2;
  const TEST_WORDS = new Set(['test', 'tests', 'pytest', 'vitest', 'בדיקה', 'בדיקות', 'e2e', 'playwright']);

  function makeTokenizer(cfg) {
    const STOP = new Set(cfg.stopwords);
    const P1 = new Set(cfg.prefix1.split(''));
    const P2 = new Set(cfg.prefix2);
    const GLOSSARY = cfg.glossary;
    const ALIASES = cfg.aliases;

    const normalize = (t) => t.normalize('NFKC').replace(/[֑-ׇ]/g, '');
    const isHebrew = (ch) => ch >= 'א' && ch <= 'ת';

    function splitIdentifier(raw) {
      const parts = [];
      for (let piece of raw.split('_')) {
        if (!piece) continue;
        piece = piece.replace(/([a-z])([A-Z])/g, '$1 $2');
        piece = piece.replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2');
        piece = piece.replace(/([A-Za-z])([0-9])|([0-9])([A-Za-z])/g,
          (m, a, b, c, d) => [a, b, c, d].filter(Boolean).join(' '));
        for (const p of piece.split(/\s+/)) if (p) parts.push(p.toLowerCase());
      }
      return parts;
    }

    function hebrewVariants(word) {
      const out = [word];
      const stems = [word];
      if (word.length >= 5 && P2.has(word.slice(0, 2))) stems.push(word.slice(2));
      if (word.length >= 4 && P1.has(word[0])) stems.push(word.slice(1));
      for (const s of stems.slice(1)) out.push(s);
      for (const s of stems) {
        if (s.length >= 5 && (s.endsWith('ים') || s.endsWith('ות'))) out.push(s.slice(0, -2));
      }
      return [...new Set(out)];
    }

    if (word.length >= 4 && P1.has(word[0])) stems.push(word.slice(1));
    for (const s of stems.slice(1)) out.push(s);
    for (const s of stems) {
      if (s.length >= 5 && (s.endsWith('ים') || s.endsWith('ות'))) out.push(s.slice(0, -2));
    }
    return [...new Set(out)];
  }

  function tokenize(text) {
    text = normalize(text);
    const tokens = [];
    const re = /[A-Za-z0-9_]+|[א-ת]+/g;
    let m;
    while ((m = re.exec(text))) {
      const raw = m[0];
      if (isHebrew(raw[0])) {
        for (const w of hebrewVariants(raw)) if (!STOP.has(w) && w.length > 1) tokens.push(w);
        continue;
      }
      const low = raw.toLowerCase();
      if (STOP.has(low) || low.length < 2 || low.length > 40) continue;
      tokens.push(low);
      const parts = splitIdentifier(raw);
      if (parts.length > 1) for (const p of parts) if (p.length > 1 && !STOP.has(p)) tokens.push(p);
    }
    return tokens;
  }

  function expandQuery(query) {
    const norm = normalize(query).toLowerCase();
    const tokens = tokenize(query);
    const extra = [];
    for (const he of Object.keys(GLOSSARY)) if (he.includes(' ') && norm.includes(he)) extra.push(...GLOSSARY[he]);
    for (const t of tokens) if (Object.prototype.hasOwnProperty.call(GLOSSARY, t)) extra.push(...GLOSSARY[t]);
    const have = new Set(tokens);
    return tokens.concat(extra.filter((e) => !have.has(e)));
  }

  function detectRepos(query) {
    const norm = normalize(query).toLowerCase();
    return Object.keys(ALIASES).filter((r) => ALIASES[r].some((a) => norm.includes(a)));
  }

  return { tokenize, expandQuery, detectRepos };
}

function isTestPath(path) {
  const p = path.toLowerCase();
  const name = p.split('/').pop();
  return p.startsWith('tests/') || p.startsWith('test/') || p.startsWith('e2e/') || p.includes('/tests/') ||
    p.includes('/e2e/') || name.startsWith('test_') || name.includes('.test.') || name.includes('.spec.');
}

function isTestPath(path) {
  const p = path.toLowerCase();
  const name = p.split('/').pop();
  return p.startsWith('tests/') || p.startsWith('test/') || p.startsWith('e2e/') || p.includes('/tests/') ||
    p.includes('/e2e/') || name.startsWith('test_') || name.includes('.test.') || name.includes('.spec.');
}

class Index {
  constructor(kb) {
    this.kb = kb;
    this.tok = makeTokenizer(kb.tokenizer);
    this.repos = Object.fromEntries(kb.repos.map((r) => [r.key, r]));
    this.chunks = kb.chunks;
    this.postings = new Map();
    this.lengths = [];
    this.chunks.forEach((c, i) => {
      const counts = new Map();
      for (const t of this.tok.tokenize(c.text)) counts.set(t, (counts.get(t) || 0) + 1);
      const meta = `${c.repo} ${c.path.split('/').join(' ').split('.').join(' ')} ${c.title}`;
      for (const t of this.tok.tokenize(meta)) counts.set(t, (counts.get(t) || 0) + META_WEIGHT);
      let len = 0;
      for (const [t, tf] of counts) {
        len += tf;
        let pl = this.postings.get(t);
        if (!pl) this.postings.set(t, (pl = []));
        pl.push([i, tf]);
      }
      this.lengths.push(len);
    });
    this.n = this.chunks.length;
    this.avgLen = this.n ? this.lengths.reduce((a, b) => a + b, 0) / this.n : 1;
  }

  idf(term) {
    const df = (this.postings.get(term) || []).length;
    return Math.log(1 + (this.n - df + 0.5) / (df + 0.5));
  }

  search(query, { k = 6, repo = null, expand = true, extraTerms = null } = {}) {
    const terms = expand ? this.tok.expandQuery(query) : this.tok.tokenize(query);
    if (extraTerms) for (const t of extraTerms) terms.push(...this.tok.tokenize(t));
    const q = new Map();
    for (const t of terms) q.set(t, (q.get(t) || 0) + 1);
    const focus = new Set(repo ? [] : this.tok.detectRepos(query));
    const wantsTests = terms.some((t) => TEST_WORDS.has(t));
    const scores = new Map();
    const matched = new Map();
    for (const [term, qtf] of q) {
      const pl = this.postings.get(term);
      if (!pl) continue;
      const w = this.idf(term) * (1 + 0.3 * (qtf - 1));
      for (const [i, tf] of pl) {
        const dl = this.lengths[i];
        scores.set(i, (scores.get(i) || 0) + w * tf * (K1 + 1) / (tf + K1 * (1 - B + B * dl / this.avgLen)));
        if (!matched.has(i)) matched.set(i, []);
        matched.get(i).push(term);
      }
    }
    const ranked = [];

        for (const [i, tf] of pl) {
          const dl = this.lengths[i];
          scores.set(i, (scores.get(i) || 0) + w * tf * (K1 + 1) / (tf + K1 * (1 - B + B * dl / this.avgLen)));
          if (!matched.has(i)) matched.set(i, []);
          matched.get(i).push(term);
        }
      }
      const ranked = [];
      for (let [i, s] of scores) {
        const c = this.chunks[i];
        if (repo && c.repo !== repo) continue;
        if (focus.has(c.repo)) s *= REPO_BOOST;
        if (c.path.toLowerCase().endsWith('readme.md')) s *= README_BOOST;
        if (!wantsTests && isTestPath(c.path)) s *= TEST_PENALTY;
        ranked.push([s, i]);
      }
      ranked.sort((a, b) => (b[0] - a[0]) || (b[1] - a[1]));
      const out = [];
      const perFile = new Map();
      for (const [s, i] of ranked) {
        const c = this.chunks[i];
        const key = c.repo + '\u0000' + c.path;
        const n = perFile.get(key) || 0;
        if (n >= MAX_PER_FILE) continue;
        perFile.set(key, n + 1);
        out.push({ chunk: c, score: s, terms: [...new Set(matched.get(i))].sort() });
        if (out.length >= k) break;
      }
      return out;
    }

    githubUrl(c) {
      const r = this.repos[c.repo] || {};
      if (!r.url) return '';
      if (c.path === '(overview)') return r.url;
      return `${r.url}/blob/${r.branch || 'main'}/${c.path}#L${c.start}-L${c.end}`;
    }
  }

  const api = { Index, makeTokenizer, isTestPath };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.YakovEngine = api;
})(typeof window !== 'undefined' ? window : globalThis);

/* A small, safe Markdown renderer for streamed answers.
 * Everything is HTML-escaped first; only the constructs below become markup.
 * Citations like [1] or [1, 3] become buttons that open the cited source. */
(function (root) {
  'use strict';

  const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  const KEYWORDS = new Set(('def class return if elif else for while in not and or import from as with try except finally raise ' +
    'lambda yield async await pass break continue None True False self function const let var new this export default ' +
    'interface type enum extends implements public private protected static readonly null undefined true false switch case ' +
    'throw catch typeof instanceof void of do').split(' '));

  // One pass over the raw code; each piece is escaped on its own, so the highlighter can never inject markup.
  function highlight(code, lang) {
    const hashComments = /^(py|python|sh|bash|yaml|yml|toml|ini|dockerfile|rb)$/i.test(lang || '');
    const re = hashComments
      ? /(#[^\n]*)|("""[\s\S]*?"""|'''[\s\S]*?'''|"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*')|\b(\d+(?:\.\d+)?)\b|\b([A-Za-z_]\w*)\b/g
      : /(\/\/[^\n]*|\/\*[\s\S]*?\*\/)|(`(?:\\.|[^`\\])*`|"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*')|\b(\d+(?:\.\d+)?)\b|\b([A-Za-z_$][\w$]*)\b/g;
    let out = '', last = 0, m;
    while ((m = re.exec(code))) {
      out += esc(code.slice(last, m.index));
      if (m[1]) out += `<span class="tk-c">${esc(m[1])}</span>`;
      else if (m[2]) out += `<span class="tk-s">${esc(m[2])}</span>`;
      else if (m[3]) out += `<span class="tk-n">${esc(m[3])}</span>`;
      else if (m[4]) out += KEYWORDS.has(m[4]) ? `<span class="tk-k">${esc(m[4])}</span>` : esc(m[4]);
      last = re.lastIndex;
    }
    return out + esc(code.slice(last));
  }

  // Some models still emit LaTeX math ($\\le 5$). Turn the common symbols into plain characters.
  const TEX = { le: '≤', leq: '≤', ge: '≥', geq: '≥', times: '×', to: '→', rightarrow: '→', leftarrow: '←', approx: '≈',
    neq: '≠', ne: '≠', pm: '±', cdot: '·', deg: '°', circ: '°', infty: '∞', sim: '~', ldots: '…', dots: '…' };
  function untex(s) {
    return s.replace(/\$([^$\n]{1,80})\$/g, (whole, body) => {
      if (!/\\[a-z]+|\^|_\{/.test(body)) return whole;            // a plain dollar amount, leave it
      return body.replace(/\^\{?\\circ\}?/g, '°').replace(/\\(?:text|mathrm|mathbf)\{([^}]*)\}/g, '$1')
        .replace(/\\([a-z]+)/g, (m, w) => TEX[w] || m)
        .replace(/[{}]/g, '').replace(/\s+/g, ' ').trim();
    });
  }

  function inline(s, ctx) {
    s = untex(s);
    // protect inline code first
    const codes = [];
    s = s.replace(/`([^`\n]+)`/g, (_, c) => { codes.push(c); return `\u0000${codes.length - 1}\u0000`; });
    s = esc(s);
    s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    s = s.replace(/(^|[^*\w])\*([^*\n]+)\*(?=[^*\w]|$)/g, '$1<em>$2</em>');
    s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, t, u) => `<a href="${u}" target="_blank" rel="noopener noreferrer">${t}</a>`);
    // citations: [1] [2, 3] [1][2]
    s = s.replace(/\[(\d{1,2}(?:\s*,\s*\d{1,2})*)\]/g, (whole, nums) => nums.split(',').map((n) => {
      n = n.trim();
      const src = ctx && ctx.sources && ctx.sources[+n - 1];
      if (!src) return `[${n}]`;
      const label = src.path === '(overview)' ? src.repo : src.path.split('/').pop();
      return `<button class="cite" data-src="${+n - 1}" title="${esc(src.repo + ' › ' + src.path + ' · ' + src.start + '–' + src.end)}">${n}<span class="sr-only"> ${esc(label)}</span></button>`;
    }).join(''));

  // citations: [1] [2, 3] [1][2]
  s = s.replace(/\[(\d{1,2}(?:\s*,\s*\d{1,2})*)\]/g, (whole, nums) => nums.split(',').map((n) => {
    n = n.trim();
    const src = ctx && ctx.sources && ctx.sources[+n - 1];
    if (!src) return `[${n}]`;
    const label = src.path === '(overview)' ? src.repo : src.path.split('/').pop();
    return `<button class="cite" data-src="${+n - 1}" title="${esc(src.repo + ' › ' + src.path + ' · ' + src.start + '–' + src.end)}">${n}<span class="sr-only"> ${esc(label)}</span></button>`;
  }).join(''));
  s = s.replace(/\u0000(\d+)\u0000/g, (_, i) => `<code>${esc(codes[+i])}</code>`);
  return s;
}

function render(md, ctx) {
  const lines = md.replace(/\r\n/g, '\n').split('\n');
  const out = [];
  let i = 0;
  let para = [];
  const flushPara = () => { if (para.length) { out.push(`<p dir="auto">${inline(para.join(' '), ctx)}</p>`); para = []; } };

  while (i < lines.length) {
    const line = lines[i];
    const fence = line.match(/^\s*(```+|~~~+)\s*([\w+#.-]*)/);
    if (fence) {
      flushPara();
      const mark = fence[1], lang = fence[2] || '';
      const body = [];
      i++;
      while (i < lines.length && !lines[i].trim().startsWith(mark)) body.push(lines[i++]);
      const closed = i < lines.length;
      i++;
      const code = body.join('\n');
      out.push(`<div class="codeblock"><header><span>${esc(lang || 'code')}</span>` +
        `<button class="copy-btn" data-copy>${ICON_COPY}<span>העתק</span></button></header>` +
        `<pre><code>${highlight(code, lang)}${closed ? '' : ''}</code></pre></div>`);
      continue;
    }
    if (/^\s*$/.test(line)) { flushPara(); i++; continue; }
    const h = line.match(/^(#{1,4})\s+(.*)$/);
    if (h) { flushPara(); out.push(`<h${h[1].length} dir="auto">${inline(h[2], ctx)}</h${h[1].length}>`); i++; continue; }
    if (/^\s*(---|\*\*\*|___)\s*$/.test(line)) { flushPara(); out.push('<hr>'); i++; continue; }
    if (/^\s*>/.test(line)) {
      flushPara();
      const q = [];
      while (i < lines.length && /^\s*>/.test(lines[i])) q.push(lines[i++].replace(/^\s*>\s?/, ''));
      out.push(`<blockquote dir="auto">${render(q.join('\n'), ctx)}</blockquote>`);
      continue;
    }
    if (/^\s*\|.*\|\s*$/.test(line) && i + 1 < lines.length && /^\s*\|?\s*:?-{2,}/.test(lines[i + 1])) {
      flushPara();
      const row = (l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
      const head = row(line);
      i += 2;
      let html = '<table dir="auto"><thead><tr>' + head.map((c) => `<th>${inline(c, ctx)}</th>`).join('') + '</tr></thead><tbody>';
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) {
        html += '<tr>' + row(lines[i++]).map((c) => `<td>${inline(c, ctx)}</td>`).join('') + '</tr>';
      }
      out.push(html + '</tbody></table>');
      continue;
    }
    if (/^\s*([-*+]|\d+[.)])\s+/.test(line)) {

      let html = '<table dir="auto"><thead><tr>' + head.map((c) => `<th>${inline(c, ctx)}</th>`).join('') + '</tr></thead><tbody>';
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) {
        html += '<tr>' + row(lines[i++]).map((c) => `<td>${inline(c, ctx)}</td>`).join('') + '</tr>';
      }
      out.push(html + '</tbody></table>');
      continue;
    }
    if (/^\s*([-*+]|\d+[.)])\s+/.test(line)) {
      flushPara();
      out.push(list(lines, i, ctx, (n) => { i = n; }));
      continue;
    }
    para.push(line.trim());
    i++;
  }
  flushPara();
  return out.join('');
}

function list(lines, start, ctx, done) {
  const indentOf = (l) => l.match(/^\s*/)[0].replace(/\t/g, '    ').length;
  const base = indentOf(lines[start]);
  const ordered = /^\s*\d+[.)]/.test(lines[start]);
  const startNum = ordered ? parseInt(lines[start].trim(), 10) : 1;
  let html = ordered ? `<ol dir="auto"${startNum !== 1 ? ` start="${startNum}"` : ''}>` : '<ul dir="auto">';
  let i = start;
  let item = null;
  const close = () => { if (item !== null) { html += `<li>${item}</li>`; item = null; } };
  while (i < lines.length) {
    const l = lines[i];
    if (/^\s*$/.test(l)) {
      // a blank line ends the list unless the next line continues it
      const nx = lines[i + 1];
      if (nx && /^\s*([-*+]|\d+[.)])\s+/.test(nx) && indentOf(nx) >= base) { i++; continue; }
      break;
    }
    const ind = indentOf(l);
    const m = l.match(/^\s*([-*+]|\d+[.)])\s+(.*)$/);
    if (m && ind === base) {
      close();
      item = inline(m[2], ctx);
      i++;
    } else if (m && ind > base) {
      item = (item || '') + list(lines, i, ctx, (n) => { i = n; });
    } else if (ind > base && item !== null) {
      item += ' ' + inline(l.trim(), ctx);
      i++;
    } else break;
  }
  close();
  done(i);
  return html + (ordered ? '</ol>' : '</ul>');
}

const ICON_COPY = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>';

    }
    close();
    done(i);
    return html + (ordered ? '</ol>' : '</ul>');
  }

  const ICON_COPY = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>';

  const api = { render, highlight, esc };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.YakovMarkdown = api;
})(typeof window !== 'undefined' ? window : globalThis);

/* yakov.LLM service worker: the app opens instantly and works offline (search runs in the page).
 * Pages and the knowledge base: network first, cache as fallback. API calls: never cached. */
const CACHE = 'yakovllm-v2';
const SHELL = ['./', './index.html', './manifest.webmanifest', './icon.svg', './icon-192.png', './icon-512.png'];

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL).catch(() => {})).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin || url.pathname.includes('/api/')) return;
  e.respondWith(
    fetch(e.request)
      .then((res) => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(e.request, copy)); }
        return res;
      })
      .catch(() => caches.match(e.request).then((hit) => hit || caches.match('./index.html'))),
  );
});

