"""Keep the knowledge base in step with a GitHub account.

Every SYNC_INTERVAL minutes (and whenever a webhook or the UI asks) we list the
user's public repositories and compare each repo's ``pushed_at`` time with the
one stored in kb.json:

* a new repo        -> cloned and indexed
* a repo with new commits -> pulled and re-indexed (only that repo)
* a deleted / archived repo -> dropped from the index

The new kb.json is written atomically and handed to ``on_update`` so the
running server swaps in the new index without a restart.
"""
from __future__ import annotations

import json
import threading
import time
from pathlib import Path
from typing import Callable

from . import ingest


class GitHubSync:
    def __init__(self, user: str, kb_path: Path, interval_min: float = 30,
                 on_update: Callable[[dict], None] | None = None):
        self.user = user
        self.kb_path = Path(kb_path)
        self.interval = max(1.0, float(interval_min)) * 60
        self.on_update = on_update
        self._lock = threading.Lock()
        self._wake = threading.Event()
        self.status: dict = {"user": user, "enabled": True, "interval_min": self.interval / 60,
                             "last_check": None, "last_change": None, "last_error": None,
                             "running": False, "last_result": None}

    # ------------------------------------------------------------------ core
    def _load(self) -> dict:
        if self.kb_path.exists():
            return json.loads(self.kb_path.read_text(encoding="utf-8"))
        return {"repos": [], "chunks": []}

    def check(self, force: bool = False) -> dict:
        """One sync pass. Returns {"added": [...], "updated": [...], "removed": [...]}."""
        if not self._lock.acquire(blocking=False):
            return {"busy": True}
        self.status["running"] = True
        try:
            listed = ingest.list_user_repos_meta(self.user)
            kb = self._load()
            if kb.get("version") != ingest.KB_VERSION:
                force = True  # the knowledge base format changed: rebuild every repo once
            repos = {r["key"]: r for r in kb["repos"]}
            chunks_by_repo: dict[str, list[dict]] = {}
            for c in kb["chunks"]:
                chunks_by_repo.setdefault(c["repo"], []).append(c)

"""
Central configuration for WiFi-Doctor.

Every threshold used by the RCA engine lives here so the decision matrix can be
audited (and tuned) in one place. All values can be overridden with environment
variables of the same name, e.g. ``GATEWAY_WARN_MS=50``.
"""

from __future__ import annotations

import os
from dataclasses import dataclass, field


def _env_str(name: str, default: str | None) -> str | None:
    value = os.getenv(name)
    return value.strip() if value and value.strip() else default


def _env_float(name: str, default: float) -> float:
    try:
        return float(os.getenv(name, default))
    except (TypeError, ValueError):
        return default


def _env_int(name: str, default: int) -> int:
    try:
        return int(os.getenv(name, default))
    except (TypeError, ValueError):
        return default


def _env_list(name: str, default: list[str]) -> list[str]:
    raw = os.getenv(name)
    if not raw:
        return default
    return [item.strip() for item in raw.split(",") if item.strip()]


@dataclass(frozen=True)
class Settings:
    # ------------------------------------------------------------------ app
    app_name: str = "WiFi-Doctor"
    version: str = "1.1.1"
    database_url: str = field(
        default_factory=lambda: _env_str(
            "DATABASE_URL", "sqlite+aiosqlite:///./data/wifi_doctor.db"
        )
    )
    cors_origins: list[str] = field(
        default_factory=lambda: _env_list(
            "CORS_ORIGINS",
            ["http://localhost:5173", "http://127.0.0.1:5173", "http://localhost:3088"],
        )
    )

    def __init__(self, maxlen: int, min_samples: int, sigma_floor_ms: float, admit_every: int = 10):
        self.samples: deque[float] = deque(maxlen=maxlen)
        self.min_samples = min_samples
        self.sigma_floor_ms = sigma_floor_ms
        self.admit_every = max(1, admit_every)
        self._held = 0

    @property
    def ready(self) -> bool:
        return len(self.samples) >= self.min_samples

    def reset(self) -> None:
        self.samples.clear()
        self._held = 0

    def stats(self) -> tuple[float | None, float | None]:
        if not self.samples:
            return None, None
        arr = np.fromiter(self.samples, dtype=float)
        median = float(np.median(arr))
        mad = float(np.median(np.abs(arr - median)))
        return median, max(self.MAD_TO_SIGMA * mad, self.sigma_floor_ms)

    def zscore(self, value: float | None) -> float | None:
        median, sigma = self.stats()
        if value is None or median is None or sigma is None:
            return None
        return (value - median) / sigma

    def observe(self, rtt_ms: float | None, anomalous: bool = False) -> None:
        """Admit a good sample. While anomalous only every Nth sample enters,
        so a sustained fault cannot quickly redefine 'normal'."""
        if rtt_ms is None:
            return
        if anomalous:
            self._held += 1
            if self._held % self.admit_every:
                return
        self.samples.append(float(rtt_ms))


class HopWindow:
    def __init__(self, hop: str, maxlen: int):
        self.hop = hop
