def _excess(value: float | None, threshold: float) -> float:
    """How far past a threshold we are, 0..1 (1 == at least 2x the threshold)."""
    if value is None:
        return 1.0
    if value == math.inf:
        return 1.0
    return max(0.0, min(1.0, value / threshold - 1.0))


