async def _emit(self) -> None:
    if self._broadcast:
        try:
            await self._broadcast({"type": "stress_test", "status": self.status()})
        except Exception:
            log.debug("stress broadcast failed", exc_info=True)

async def _execute(self) -> None:
    stop = threading.Event()
    counters = TransferCounters()
    timeout = max(1.0, self.s.probe_timeout_s * 4)
    workers = [
        asyncio.create_task(asyncio.to_thread(self._transfer, list(self.s.stress_download_urls), "down", stop, counters, timeout))
        for _ in range(max(1, self.s.stress_download_workers))
    ] + [
        asyncio.create_task(asyncio.to_thread(self._transfer, list(self.s.stress_upload_urls), "up", stop, counters, timeout))
        for _ in range(max(0, self.s.stress_upload_workers))
    ]
    peaks = {"down": 0.0, "up": 0.0}
    try:
        await asyncio.wait_for(self._drive(counters, peaks), timeout=self.timeout_s)
        down, up = counters.snapshot()
        if down + up == 0:
            self.state = "failed"
            self.error = "Could not reach any speed-test endpoint (offline, firewalled or blocked)."
        else:
            assert self._run is not None
            self.result = compute_result(
                self._run.unloaded, self._run.loaded, peaks["down"], peaks["up"], down, up, counters.endpoint
            )
            self.state = "completed"
    except asyncio.TimeoutError:
        self.state = "aborted"
        self.error = f"Aborted by the {self.timeout_s:.0f}s safety timeout."
    except asyncio.CancelledError:
        self.state = "aborted"
        self.error = "Cancelled."
        raise
    except Exception as exc:  # never let a test crash the service
        log.exception("bufferbloat test failed")
        self.state = "failed"
        self.error = f"{exc.__class__.__name__}: {exc}"
    finally:

        dl = self.download_mbps / self.peak_download_mbps if self.peak_download_mbps else 0.0
        ul = self.upload_mbps / self.peak_upload_mbps if self.peak_upload_mbps else 0.0
        return round(min(max(dl, ul), 1.0) * 100.0, 1)

    @property
    def total_mbps(self) -> float:
        return self.download_mbps + self.upload_mbps

    def to_dict(self) -> dict[str, Any]:
        return {
            "download_mbps": round(self.download_mbps, 3),
            "upload_mbps": round(self.upload_mbps, 3),
            "peak_download_mbps": round(self.peak_download_mbps, 2),
            "peak_upload_mbps": round(self.peak_upload_mbps, 2),
            "utilization_pct": self.utilization_pct,
            "interface": self.interface,
            "link_speed_mbps": self.link_speed_mbps,
            "is_wireless": self.is_wireless,
            "top_process": self.top_process,
            "simulated": self.simulated,
        }


def _is_wireless(nic: str | None) -> bool | None:
    if not nic:
        return None
    if Path(f"/sys/class/net/{nic}/wireless").exists() or Path(f"/sys/class/net/{nic}/phy80211").exists():
        return True
    lowered = nic.lower()
    if any(lowered.startswith(h) or h in lowered for h in _WIRELESS_HINTS):
        return True
    if lowered.startswith(("eth", "en", "ethernet")) and not lowered.startswith("en0"):
        return False
    return None


