    mhz = int(round(mhz))
    if mhz == 2484:
        return 14
    if 2412 <= mhz <= 2472:
        return (mhz - 2407) // 5
    if 5955 <= mhz <= 7115:
        return (mhz - 5950) // 5
    if 4910 <= mhz <= 5895:
        return (mhz - 5000) // 5
    return None

