const remember = (k: string, v?: string) => {
  try {
    if (v === undefined) return localStorage.getItem(`pp-conn-${k}`) ?? "";
    localStorage.setItem(`pp-conn-${k}`, v);
  } catch {
    /* storage unavailable */
  }
  return v ?? "";
};

