function pick(cols: ColumnProfile[], role: Role, used: Set<string>): string | undefined {
  const ok = cols.filter((c) => !used.has(c.name) && ROLE_TYPES[role].includes(c.type));
  const hit = ok.find((c) => HINTS[role].test(c.name));
  if (hit) return hit.name;
  // A lone datetime column is the timestamp even when its name gives no hint
  if (role === "timestamp") return ok.find((c) => c.type === "datetime")?.name;
  return undefined;
}

export function suggestMapping(kind: DatasetKind, cols: ColumnProfile[]): Mapping {
  const used = new Set<string>();
  const m: Mapping = {};
  const roles = [...KIND_INFO[kind].required, ...KIND_INFO[kind].optional].filter((r) => r !== "segment");
  for (const r of roles) {
    const c = pick(cols, r, used);
    if (c) {
      m[r] = c;
      used.add(c);
    }
  }
  if (kind === "events" || kind === "experiment" || kind === "funnel_summary") {
    m.segments = cols
      .filter((c) => !used.has(c.name) && c.type === "category" && c.distinct >= 2 && c.distinct <= 30)
      .map((c) => c.name)
      .slice(0, 3);
  }
  return m;
}

/** Score each dataset kind by how many of its required roles can be filled. */
export function detectKind(cols: ColumnProfile[], rows: number): DatasetKind {
  const score = (k: DatasetKind) => {
    const m = suggestMapping(k, cols);
    const req = KIND_INFO[k].required;
    const filled = req.filter((r) => m[r]).length;
    const opt = KIND_INFO[k].optional.filter((r) => r !== "segment" && m[r]).length;
    return filled === req.length ? 10 + filled * 2 + opt : filled;
  };
  const kinds: DatasetKind[] = ["experiment_summary", "ai_eval", "experiment", "funnel_summary", "events"];
  let best: DatasetKind = "events";
  let bestScore = -1;
  for (const k of kinds) {
    let s = score(k);
    if (k === "experiment_summary" && rows > 20) s -= 20; // summaries are tiny
    // Aggregated funnels have no per-user id column; event logs do
    if (k === "funnel_summary" && cols.some((c) => c.type === "id")) s -= 20;
    if (k === "events" && !cols.some((c) => c.type === "id")) s -= 5;
    if (s > bestScore) {
      bestScore = s;
      best = k;

    let s = score(k);
    if (k === "experiment_summary" && rows > 20) s -= 20; // summaries are tiny
    // Aggregated funnels have no per-user id column; event logs do
    if (k === "funnel_summary" && cols.some((c) => c.type === "id")) s -= 20;
    if (k === "events" && !cols.some((c) => c.type === "id")) s -= 5;
    if (s > bestScore) {
      bestScore = s;
      best = k;
    }
  }
  return best;
}

export function missingRoles(kind: DatasetKind, m: Mapping): Role[] {
  return KIND_INFO[kind].required.filter((r) => !m[r]);
}

const nf = new Intl.NumberFormat("en-US");

export const fmtInt = (n: number | null | undefined) => (n == null ? "—" : nf.format(Math.round(n)));

export const fmtPct = (x: number | null | undefined, digits = 1, signed = false) => {
  if (x == null || !Number.isFinite(x)) return "—";
  const s = `${(x * 100).toFixed(digits)}%`;
  return signed && x > 0 ? `+${s}` : s;
};

/** For values already expressed in 0–100. */
export const fmtPct100 = (x: number | null | undefined, digits = 1) =>
  x == null ? "—" : `${Number(x).toFixed(digits)}%`;

export const fmtP = (p: number | null | undefined) => {
  if (p == null) return "—";
  if (p < 0.0001) return "< 0.0001";
  if (p < 0.01) return p.toFixed(4);
  return p.toFixed(3);
};

export const fmtProb = (p: number) => (p > 0.999 ? "> 99.9%" : p < 0.001 ? "< 0.1%" : fmtPct(p, 1));

export const fmtMs = (ms: number | null | undefined) =>
  ms == null ? "—" : ms >= 1000 ? `${(ms / 1000).toFixed(2)} s` : `${Math.round(ms)} ms`;

export const fmtUsd = (x: number | null | undefined, digits = 2) => (x == null ? "—" : `$${x.toFixed(digits)}`);

export const stageLabel = (s: string) =>
  s
    .toLowerCase()
    .split("_")
    .map((w) => w[0]!.toUpperCase() + w.slice(1))
    .join(" ");

/** Relation + value: "= 0.012" or "< 0.0001". */
export const fmtPEq = (p: number | null | undefined) => (p == null ? "= —" : p < 0.0001 ? "< 0.0001" : `= ${fmtP(p)}`);

