  return t >= 0 ? tail : 1 - tail;
}

/** Student-t survival function P(T > t). */
export function tSf(t: number, df: number): number {
  const x = df / (df + t * t);
  const tail = 0.5 * betaInc(x, df / 2, 0.5);
  return t >= 0 ? tail : 1 - tail;
}

export function tPpf(p: number, df: number): number {
  let lo = -1e4;
