/** Marsaglia–Tsang gamma sampler (shape ≥ 1; boosts for shape < 1). */
function gammaSample(shape: number, u: () => number, n: () => number): number {
  if (shape < 1) return gammaSample(shape + 1, u, n) * Math.pow(u(), 1 / shape);
  const d = shape - 1 / 3;
