class Metrics:
    """In-memory KPI counters, seeded from PostgreSQL on startup."""

    def __init__(self) -> None:
        self._events: deque[float] = deque(maxlen=10_000)
        self._latency: deque[float] = deque(maxlen=500)
        self.total_processed = 0
        self.total_blocked = 0
        self.total_review = 0
        self.pending_reviews = 0
        self.blocked_amount = 0.0
        self.fraud_total = 0
        self.fraud_flagged = 0
        self.normal_total = 0
        self.normal_flagged = 0

    async def load(self, session: AsyncSession) -> None:
        """Rebuild counters from persisted data."""
        flagged = Transaction.decision != Decision.APPROVE.value
        row = (
            await session.execute(
                select(
                    func.count(),
                    func.count().filter(Transaction.final_decision == Decision.BLOCK.value),
                    func.count().filter(Transaction.decision == Decision.REVIEW.value),
                    func.count().filter(Transaction.review_status == ReviewStatus.PENDING.value),
                    func.coalesce(
                        func.sum(case((Transaction.final_decision == Decision.BLOCK.value, Transaction.amount), else_=0)),
                        0,
                    ),
                    func.count().filter(Transaction.sim_pattern.is_not(None)),
                    func.count().filter(Transaction.sim_pattern.is_not(None), flagged),
                    func.count().filter(Transaction.sim_pattern.is_(None)),
                    func.count().filter(Transaction.sim_pattern.is_(None), flagged),
                )
            )
        ).one()
        (
            self.total_processed,
            self.total_blocked,
            self.total_review,
            self.pending_reviews,
            blocked_amount,
            self.fraud_total,
            self.fraud_flagged,

    self.generated = 0
    self.fraud_injected = 0
    self._running = asyncio.Event()
    self._busy_until: dict[str, float] = {}
    self._loop_task: asyncio.Task[None] | None = None
    self._scenarios: set[asyncio.Task[None]] = set()
    self.on_state_change: Callable[[SimulatorState], Awaitable[None]] | None = None

# ------------------------------------------------------------- lifecycle
async def start(self) -> None:
    """Publish cardholder baselines and launch the generator loop."""
    await self.redis.save_profiles(self.profiles)
    if settings.sim_autostart:
        self._running.set()
    self._loop_task = asyncio.create_task(self._loop(), name="simulator-loop")
    logger.info("Simulator ready with %d cardholders (running=%s)", len(self.profiles), self.running)

async def stop(self) -> None:
    """Cancel the loop and any in-flight scenarios."""
    tasks = [t for t in (self._loop_task, *self._scenarios) if t]
    for t in tasks:
        t.cancel()
    for t in tasks:
        with contextlib.suppress(asyncio.CancelledError):
            await t

@property
def running(self) -> bool:
    """Whether traffic is flowing."""
    return self._running.is_set()

def state(self) -> SimulatorState:
    """Snapshot of the simulator settings and counters."""
    return SimulatorState(
        running=self.running,
        tps=self.tps,
        fraud_rate=self.fraud_rate,
        max_tps=settings.sim_max_tps,
        generated=self.generated,
        fraud_injected=self.fraud_injected,
    )

async def update(self, upd: SimulatorUpdate) -> SimulatorState:
    """Apply a partial settings update."""
    if upd.tps is not None:
        self.tps = min(upd.tps, settings.sim_max_tps)
    if upd.fraud_rate is not None:
        self.fraud_rate = upd.fraud_rate
    if upd.running is True:
        self._running.set()
    elif upd.running is False:
        self._running.clear()
    await self._notify()
    return self.state()

