import { createContext, ReactNode, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { api, getToken, setToken, setUnauthorizedHandler } from "../api/client";
import type { Me, User } from "../api/types";

interface AuthValue {
  me: Me | null;
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<User>;
  register: (data: { email: string; password: string; first_name: string; last_name: string; role: "Trainee" | "Trainer" }) => Promise<User>;
  logout: () => void;
  refresh: () => Promise<void>;
}

const Ctx = createContext<AuthValue | null>(null);
const ME_CACHE = "fv:me";

export function AuthProvider({ children }: { children: ReactNode }) {
  const [me, setMe] = useState<Me | null>(() => {
    try {
      const raw = localStorage.getItem(ME_CACHE);
      return raw && getToken() ? (JSON.parse(raw) as Me) : null; // instant first paint, refreshed below
    } catch {
      return null;
    }
  });
  const [loading, setLoading] = useState<boolean>(!!getToken() && !me);

  const store = (m: Me | null) => {
    setMe(m);
    try {
      if (m) localStorage.setItem(ME_CACHE, JSON.stringify(m));
      else localStorage.removeItem(ME_CACHE);
    } catch {
      /* ignore */
    }
  };

  const refresh = useCallback(async () => {
    if (!getToken()) {
      store(null);
      setLoading(false);
      return;
    }
    try {
      store(await api<Me>("/me"));
    } catch (e: any) {
      if (e?.status === 401) store(null); // offline keeps the cached profile
    } finally {
      setLoading(false);
    }
  }, []);

  const logout = useCallback(() => {
    setToken(null);
    store(null);
  }, []);

    }
  }, []);

  const logout = useCallback(() => {
    setToken(null);
    store(null);
  }, []);

  useEffect(() => {
    setUnauthorizedHandler(logout);
    void refresh();
  }, [logout, refresh]);

  const login = useCallback(
    async (email: string, password: string) => {
      const out = await api<{ access_token: string; user: User }>("/auth/login", { method: "POST", json: { email, password } });
      setToken(out.access_token);
      await refresh();
      return out.user;
    },
    [refresh],
  );

  const register = useCallback(
    async (data: { email: string; password: string; first_name: string; last_name: string; role: "Trainee" | "Trainer" }) => {
      const out = await api<{ access_token: string; user: User }>("/auth/register", { method: "POST", json: data });
      setToken(out.access_token);
      await refresh();
      return out.user;
    },
    [refresh],
  );

  const value = useMemo(() => ({ me, user: me?.user ?? null, loading, login, register, logout, refresh }), [me, loading, login, register, logout, refresh]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useAuth(): AuthValue {
  const v = useContext(Ctx);
  if (!v) throw new Error("useAuth outside AuthProvider");
  return v;
}

/** Last-resort screen instead of a blank page, e.g. when a screen's code cannot be downloaded offline. */
import { Component, ReactNode } from "react";

export default class ErrorBoundary extends Component<{ children: ReactNode }, { error: Error | null }> {
  state = { error: null as Error | null };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  render() {
    if (!this.state.error) return this.props.children;
    const offline = typeof navigator !== "undefined" && !navigator.onLine;
    return (
      <div className="auth">
        <div className="card stack" role="alert" data-testid="app-error">
          <h3>{offline ? "אין חיבור לרשת" : "משהו השתבש"}</h3>
          <p className="small muted">
            {offline ? "המסך הזה עוד לא נשמר במכשיר. האימונים שכבר נשמרו לא יאבדו." : "אפשר לטעון את הדף מחדש."}
          </p>
          <p className="dev">{this.state.error.message}</p>
          <button onClick={() => location.reload()}>טעינה מחדש</button>
        </div>
      </div>
    );
  }
}

/**
 * "Install as an app": FitVision is a PWA, so it installs from the browser on any device with a camera —
 * Android (Chrome, Samsung Internet), iPhone and iPad (Safari → Share → Add to Home Screen), and laptops
 * (Chrome or Edge → Install). Once installed it opens full screen from its own icon, like a store app.
 */
import { useEffect, useState } from "react";

interface BeforeInstallPrompt extends Event {
  prompt: () => Promise<void>;
}

const standalone = () =>
  window.matchMedia?.("(display-mode: standalone)").matches || (navigator as unknown as { standalone?: boolean }).standalone === true;
const isIos = () => /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);

export default function InstallApp() {
  const [evt, setEvt] = useState<BeforeInstallPrompt | null>(null);
  const [hidden, setHidden] = useState(() => {
    try {
      return standalone() || localStorage.getItem("fv:install-hidden") === "1";
    } catch {
      return standalone();
    }
  });
  const [iosHelp, setIosHelp] = useState(false);

  useEffect(() => {
    const on = (e: Event) => {
      e.preventDefault();
      setEvt(e as BeforeInstallPrompt);
    };
    window.addEventListener("beforeinstallprompt", on);
    return () => window.removeEventListener("beforeinstallprompt", on);
  }, []);

  if (hidden || (!evt && !isIos())) return null;
  const close = () => {
    setHidden(true);
    try {
      localStorage.setItem("fv:install-hidden", "1");
    } catch {
      /* ignore */
    }
  };
  return (
    <div className="card install" data-testid="install-app">
      <div className="spread">
        <div>
          <b>📲 התקנה כאפליקציה</b>
          <div className="muted small">אייקון במסך הבית, מסך מלא, ועבודה גם בלי רשת</div>
        </div>
        <div className="row">
          <button
            onClick={async () => {
              if (evt) {
                await evt.prompt();
                setEvt(null);
                close();
              } else setIosHelp(!iosHelp);
            }}

