/** Messages exchanged between the UI thread and the pose worker. Only landmarks cross back — never pixels to a server. */
import type { Point3 } from "./geometry";

export type ModelVariant = "full" | "lite";

export type ToWorker =
  | { type: "init"; model: ModelVariant }
  | { type: "frame"; bitmap: ImageBitmap; timestamp: number };

export type FromWorker =
  | { type: "ready"; model: ModelVariant }
  | { type: "error"; message: string }
  | {
      type: "result";
      timestamp: number;
      inferenceMs: number;
      landmarks: Point3[] | null;
      worldLandmarks: Point3[] | null;
    };

/** Rolling performance metrics for the PoC: FPS of processed frames, latency percentiles. */

export class Metrics {
  private stamps: number[] = [];
  private latencies: number[] = [];
  private inference: number[] = [];
  private startedAt = performance.now();

  record(latencyMs: number, inferenceMs: number): void {
    const now = performance.now();
    this.stamps.push(now);
    this.latencies.push(latencyMs);
    this.inference.push(inferenceMs);
    while (this.stamps.length && now - this.stamps[0] > 1000) this.stamps.shift();
    if (this.latencies.length > 300) this.latencies.shift();
    if (this.inference.length > 300) this.inference.shift();
  }

  fps(): number {
    return this.stamps.length;
  }

  /** After 3 s of warm-up, fewer than 15 processed frames per second (NFR-02). */
  shouldFallBack(): boolean {
    return performance.now() - this.startedAt > 3000 && this.fps() < 15;
  }

  summary(model: string): string {
    return `מודל: ${model} · FPS: ${this.fps()} · השהיה חציונית: ${percentile(this.latencies, 50).toFixed(0)}ms · p95: ${percentile(this.latencies, 95).toFixed(0)}ms · הסקה: ${percentile(this.inference, 50).toFixed(0)}ms`;
  }

  reset(): void {
    this.stamps = [];
    this.latencies = [];
    this.inference = [];
    this.startedAt = performance.now();
  }
}

export function percentile(values: number[], p: number): number {
  if (!values.length) return NaN;
  const sorted = [...values].sort((a, b) => a - b);
  const idx = Math.min(sorted.length - 1, Math.ceil((p / 100) * sorted.length) - 1);
  return sorted[Math.max(0, idx)];
}

/// <reference lib="webworker" />
/**
 * Runs MediaPipe Pose Landmarker off the UI thread (VIDEO mode, detectForVideo).
 * Receives ImageBitmap frames, returns 33 image landmarks + 33 world landmarks (metres).
 */
import { FilesetResolver, PoseLandmarker } from "@mediapipe/tasks-vision";
import type { FromWorker, ModelVariant, ToWorker } from "./messages";

const WASM_URL = "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14/wasm";
const MODEL_URL: Record<ModelVariant, string> = {
  full: "https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_full/float16/latest/pose_landmarker_full.task",
  lite: "https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/latest/pose_landmarker_lite.task",
};

let landmarker: PoseLandmarker | null = null;
const post = (msg: FromWorker) => (self as unknown as DedicatedWorkerGlobalScope).postMessage(msg);

async function init(model: ModelVariant): Promise<void> {
  landmarker?.close();
  const vision = await FilesetResolver.forVisionTasks(WASM_URL);
  landmarker = await PoseLandmarker.createFromOptions(vision, {
    baseOptions: { modelAssetPath: MODEL_URL[model], delegate: "GPU" },
    runningMode: "VIDEO",
    numPoses: 1,
  });
  post({ type: "ready", model });
}

self.onmessage = async (e: MessageEvent<ToWorker>) => {
  const msg = e.data;
  try {
    if (msg.type === "init") {
      await init(msg.model);
      return;
    }
    if (!landmarker) {
      msg.bitmap.close();
      return;
    }
    const t0 = performance.now();
    const res = landmarker.detectForVideo(msg.bitmap, msg.timestamp);
    msg.bitmap.close();
    post({
      type: "result",
      timestamp: msg.timestamp,
      inferenceMs: performance.now() - t0,
      landmarks: res.landmarks[0] ?? null,
      worldLandmarks: res.worldLandmarks[0] ?? null,
    });
  } catch (err) {
    post({ type: "error", message: String(err) });
  }
};

