"""Cache and counters on Redis (section 6.3.2), with an in-process fallback for tests and local runs."""
from __future__ import annotations

import json
import threading
import time
from typing import Any

from .config import settings

try:
    import redis  # type: ignore
except ImportError:  # pragma: no cover
    redis = None


class _Memory:
    def __init__(self) -> None:
        self._d: dict[str, tuple[float | None, str]] = {}
        self._lock = threading.Lock()

    def get(self, key: str) -> str | None:
        with self._lock:
            item = self._d.get(key)
            if item is None:
                return None
            exp, val = item
            if exp is not None and exp < time.time():
                del self._d[key]
                return None
            return val

    def set(self, key: str, value: str, ex: int | None = None) -> None:
        with self._lock:
            self._d[key] = (time.time() + ex if ex else None, value)

    def delete(self, *keys: str) -> None:
        with self._lock:
            for k in keys:
                self._d.pop(k, None)

    def incr(self, key: str) -> int:
        with self._lock:
            exp, val = self._d.get(key, (None, "0"))
            n = int(val) + 1
            self._d[key] = (exp, str(n))
            return n

    def expire(self, key: str, seconds: int) -> None:
        with self._lock:
            if key in self._d:
                self._d[key] = (time.time() + seconds, self._d[key][1])

    def flushall(self) -> None:
        with self._lock:
            self._d.clear()

            if key in self._d:
                self._d[key] = (time.time() + seconds, self._d[key][1])

    def flushall(self) -> None:
        with self._lock:
            self._d.clear()


def _client():
    if settings.redis_url and redis is not None:
        return redis.Redis.from_url(settings.redis_url, decode_responses=True)
    return _Memory()


client = _client()


def get_json(key: str) -> Any | None:
    try:
        raw = client.get(key)
    except Exception:  # cache failures never break a request
        return None
    return json.loads(raw) if raw else None


def set_json(key: str, value: Any, ttl: int) -> None:
    try:
        client.set(key, json.dumps(value, default=str, ensure_ascii=False), ex=ttl)
    except Exception:
        pass


def invalidate(*keys: str) -> None:
    try:
        client.delete(*keys)
    except Exception:
        pass


def hit_counter(key: str, window_seconds: int) -> int:
    n = client.incr(key)
    if n == 1:
        client.expire(key, window_seconds)
    return n


# cache keys
def k_rules(exercise_id: int) -> str:
    return f"rules:{exercise_id}"


def k_dashboard(trainer_id: int) -> str:
    return f"dash:{trainer_id}"


def k_alerts(trainer_id: int) -> str:
    return f"alerts:{trainer_id}"

"""Database engine and session factory (SQL Server in production, SQLite in tests)."""
from __future__ import annotations

from collections.abc import Iterator

from sqlalchemy import create_engine, event
from sqlalchemy.orm import DeclarativeBase, Session, sessionmaker

from .config import settings


class Base(DeclarativeBase):
    pass


def normalize_url(url: str) -> str:
    """Hosted Postgres (Neon, Render, Supabase) hands out postgres:// URLs; SQLAlchemy needs the driver name."""
    for prefix in ("postgres://", "postgresql://"):
        if url.startswith(prefix):
            return "postgresql+psycopg://" + url[len(prefix):]
    return url


def make_engine(url: str):
    url = normalize_url(url)
    kwargs: dict = {"pool_pre_ping": True}
    if url.startswith("sqlite"):
        kwargs["connect_args"] = {"check_same_thread": False}
    elif url.startswith("mssql"):
        kwargs["fast_executemany"] = True
    eng = create_engine(url, **kwargs)
    if url.startswith("sqlite"):
        @event.listens_for(eng, "connect")
        def _fk_on(dbapi_conn, _):  # enforce FKs like SQL Server does
            cur = dbapi_conn.cursor()
            cur.execute("PRAGMA foreign_keys=ON")
            cur.close()
    return eng


engine = make_engine(settings.database_url)
SessionLocal = sessionmaker(bind=engine, autoflush=False, expire_on_commit=False)


def get_db() -> Iterator[Session]:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

"""Background work on an RQ queue (section 6.3.2). Without REDIS_URL, jobs run inline."""
from __future__ import annotations

import uuid
from collections.abc import Callable
from typing import Any

from .config import settings

_inline_results: dict[str, dict[str, Any]] = {}


def _queue():
    if not settings.redis_url:
        return None
    from redis import Redis
    from rq import Queue

    return Queue("fitvision", connection=Redis.from_url(settings.redis_url))


def enqueue(func: Callable[..., Any], *args: Any) -> tuple[str, bool]:
    """Returns (job_id, queued). queued=False means the job already ran inline."""
    q = _queue()
    if q is None:
        job_id = uuid.uuid4().hex
        try:
            _inline_results[job_id] = {"status": "finished", "result": func(*args)}
        except Exception as exc:  # surface the failure through the job status
            _inline_results[job_id] = {"status": "failed", "error": str(exc)}
        return job_id, False
    job = q.enqueue(func, *args, job_timeout=120, result_ttl=3600)
    return job.id, True


def status(job_id: str) -> dict[str, Any]:
    if job_id in _inline_results:
        return _inline_results[job_id]
    q = _queue()
    if q is None:
        return {"status": "unknown"}
    from rq.exceptions import NoSuchJobError
    from rq.job import Job

    try:
        job = Job.fetch(job_id, connection=q.connection)
    except NoSuchJobError:
        return {"status": "unknown"}
    st = job.get_status(refresh=True)
    out: dict[str, Any] = {"status": str(st.value if hasattr(st, "value") else st)}
    if out["status"] == "finished":
        out["result"] = job.return_value()
    if out["status"] == "failed":
        out["error"] = "job failed"
    return out

    # the pose worker loads MediaPipe with importScripts() and WebAssembly.instantiateStreaming(), which reject wrong MIME types
    mimetypes.add_type("text/javascript", ".js")
    mimetypes.add_type("application/wasm", ".wasm")
    static_dir = os.getenv("STATIC_DIR")
    if static_dir and Path(static_dir).is_dir():
        root = Path(static_dir).resolve()
        app.mount("/assets", StaticFiles(directory=root / "assets"), name="assets")

        @app.get("/{path:path}", include_in_schema=False)
        def spa(path: str):
            f = (root / path).resolve()
            if path and f.is_file() and root in f.parents:
                return FileResponse(f)
            return FileResponse(root / "index.html")

    if settings.enable_scheduler:
        _start_scheduler()
    return app


