const runSeeds = [1, 42, 1337, 20261113, 987654321]
let total = 0
let worstMs = 0
let sumMs = 0
let fallbacks = 0
let maxAttempts = 0
const lieTypeCount: Record<string, number> = {}
for (const runSeed of runSeeds) {
