      if (ch === 'I') lies.push({ id: lies.length, type: 'illusionFloor', cells: [{ x, y }] })
      if (ch === 'D' || ch === 'B') lies.push({ id: lies.length, type: 'disguisedTrap', cells: [{ x, y }] })
      if (ch === 'X' || ch === 'e') pairs.exit.push({ x, y })
      if (ch === 'Y' || ch === 't') pairs.treasure.push({ x, y })
    })
    truth.push(tRow)
    map.push(mRow)
