    @staticmethod
    def _font_candidates():
        """Font files that usually contain Hebrew, most likely first."""
        windir = os.environ.get("WINDIR", r"C:\Windows")
        paths = [os.path.join(windir, "Fonts", f) for f in config.HEBREW_FONT_FILES]
